{"source": "def investigate(context, acquire):
    events = acquire("events")
    seen = {}
    for record in events:
        event_id = record["event_id"]
        work = record["work"]
        if event_id not in seen:
            seen[event_id] = work
    ratio = 0
    for event_id in seen:
        ratio = ratio + seen[event_id]
    return {"findings": [], "unresolved": [], "ratio": ratio}", "scope": "Deduplicate event records by event_id and sum work once per unique id.", "lesson": "Duplicate deliveries must be collapsed by identity, while distinct ids with equal work remain separate contributions."}
